	withPathDir(t, dir)
	calls := interceptVersionCheck(t)

	handled, code := MaybeRunPlugin(context.Background(), newTestRoot(), []string{"upgrade", "--nightly"})
	if !handled || code != 0 {
		t.Fatalf("handled=%v code=%d, want handled=true code=0", handled, code)
	}
