	dir := t.TempDir()
	writePluginBinary(t, dir, "entire-help", filepath.Join(dir, "args.txt"), 0)
	withPathDir(t, dir)

	// Use a Cobra-style root that mirrors NewRootCmd: SetHelpCommand only
	// stashes the help command on the struct — it is not in the tree until
