// onDemandPluginInstall shares the normal install workflow, including index
// overrides, name/checksum validation and dependency confirmation. Tests replace
// it to exercise the prompt and dispatch without downloading real releases.
var onDemandPluginInstall = runRemoteInstall

func installMissingPlugin(ctx context.Context, rootCmd *cobra.Command, name string) (string, error) {
	if !interactive.CanPromptInteractively() {
		return "", fmt.Errorf("the entire-%s plugin is not installed; run 'entire plugin install %s' and retry", name, name)
	}
	if err := ctx.Err(); err != nil {
		return "", fmt.Errorf("install plugin: %w", err)
	}
	confirmed := true
	form := NewAccessibleForm(huh.NewGroup(
		huh.NewConfirm().Title(fmt.Sprintf("Install the entire-%s plugin?", name)).Value(&confirmed),
	)).WithInput(rootCmd.InOrStdin()).WithOutput(rootCmd.ErrOrStderr())
	if err := form.RunWithContext(ctx); err != nil {
		return "", handleFormCancellation(rootCmd.ErrOrStderr(), "Install", err)
	}
	if !confirmed {
		fmt.Fprintln(rootCmd.ErrOrStderr(), "Install cancelled.")
		return "", nil
	}
	if err := ctx.Err(); err != nil {
		return "", fmt.Errorf("install plugin: %w", err)
	}

	// Keep install progress off stdout: the original command may emit JSON or
	// be piped to another tool. Do not parse any of the plugin's arguments.
	cmd := newPluginInstallCmd()
	cmd.SetOut(rootCmd.ErrOrStderr())
	cmd.SetErr(rootCmd.ErrOrStderr())
	if err := onDemandPluginInstall(ctx, cmd, installSource{Kind: installFromIndex, Ref: name}, remoteInstallFlags{}); err != nil {
		return "", err
	}
	installed, err := FindInstalledPlugin(name)
	if err != nil {
		return "", err
	}
	if installed == nil {
		return "", fmt.Errorf("the entire-%s plugin was not installed; run 'entire plugin install %s' and retry", name, name)
	}
	// Execute the managed entry directly, even if the managed directory could
	// not be prepended to PATH at startup.
	return installed.Path, nil
}

// MaybeRunPlugin returns (true, exitCode) when an external command was
// resolved and run. On launch failure (e.g. missing executable bit)
// returns (true, 1) after printing to stderr. On no-match returns
// (false, 0) so the caller can fall through to Cobra.
//
// Telemetry and the version-check notice mirror Cobra's PersistentPostRun
// behavior for built-ins: both fire only on a successful (exit-0) run.
func MaybeRunPlugin(ctx context.Context, rootCmd *cobra.Command, args []string) (handled bool, exitCode int) {
	binPath, pluginArgs, ok := resolvePlugin(rootCmd, args)
	if !ok {
		return false, 0
	}
	pluginName := args[0]
	if binPath == "" {
		var err error
		binPath, err = installMissingPlugin(ctx, rootCmd, pluginName)
		if err != nil {
			fmt.Fprintln(rootCmd.ErrOrStderr(), RenderUserFacingError(err))
			return true, 1
		}
		if binPath == "" {
			// The command was not executed because installation was declined.
			return true, 1
		}
	}
	exitCode = runPlugin(ctx, pluginName, binPath, pluginArgs)
	if exitCode == 0 {
		maybeTrackPluginInvocation(ctx, pluginName)
		// Stderr, matching the built-in PersistentPostRun: the plugin's own
		// stdout may be machine-readable and piped.
		//
		// Skipped after a self-update: this process still carries the
		// pre-upgrade compiled-in version, so the check would see itself as
		// outdated and prompt to redo the upgrade that just completed.
		if pluginName != selfUpdatePluginName {
			postPluginVersionCheck(ctx, os.Stderr, versioninfo.Version)
		}
	}
	return true, exitCode
}

// maybeTrackPluginInvocation fires telemetry only for plugins on the
// official allowlist. Third-party plugin names are never sent — see
// IsOfficialPlugin for the rationale.
func maybeTrackPluginInvocation(ctx context.Context, pluginName string) {
	if !IsOfficialPlugin(pluginName) {
	}
}

func TestMaybeRunPlugin_InstallGraphAndRun(t *testing.T) { //nolint:paralleltest // isolates environment and installer seam
	for _, tc := range []struct {
		name        string
		answer      string
		installErr  error
		pluginCode  int
		wantCode    int
		wantInstall bool
		wantRun     bool
	}{
		{name: "enter accepts default yes", answer: "\n", wantInstall: true, wantRun: true},
		{name: "explicit yes preserves exit code", answer: "y\n", pluginCode: 42, wantCode: 42, wantInstall: true, wantRun: true},
		{name: "no cancels", answer: "n\n", wantCode: 1},
		{name: "failed install does not run", answer: "\n", installErr: errors.New("download failed"), wantCode: 1, wantInstall: true},
	} {
		t.Run(tc.name, func(t *testing.T) {
			dir := t.TempDir()
			t.Setenv("PATH", dir)
			t.Setenv("ENTIRE_PLUGIN_DIR", filepath.Join(dir, "managed"))
			t.Setenv("ENTIRE_TEST_TTY", "1")
			t.Setenv("ACCESSIBLE", "1")
			t.Setenv("ENTIRE_TELEMETRY_OPTOUT", "1")
			interceptVersionCheck(t)
			argFile := filepath.Join(dir, "args.txt")
			sourceDir := t.TempDir()
			source := writePluginBinary(t, sourceDir, "entire-graph", argFile, tc.pluginCode)
			installCalls := 0
			original := onDemandPluginInstall
			onDemandPluginInstall = func(_ context.Context, cmd *cobra.Command, src installSource, flags remoteInstallFlags) error {
				installCalls++
				if src.Kind != installFromIndex || src.Ref != "graph" || flags != (remoteInstallFlags{}) {
					t.Fatalf("unexpected install request: %+v %+v", src, flags)
				}
				if tc.installErr != nil {
					return tc.installErr
				}
				_, err := InstallPluginFromPath(InstallPluginOptions{SourcePath: source})
				fmt.Fprintln(cmd.OutOrStdout(), "Installed graph")
				return err
			}
			t.Cleanup(func() { onDemandPluginInstall = original })
			root := newTestRoot()
			var stdout, stderr bytes.Buffer
			root.SetOut(&stdout)
			root.SetErr(&stderr)
			root.SetIn(strings.NewReader(tc.answer))
			args := []string{"graph", "search", "two words", "--json", "--", "$(untouched)", ""}
			handled, code := MaybeRunPlugin(t.Context(), root, args)
			if !handled || code != tc.wantCode {
				t.Fatalf("handled=%v code=%d, want true, %d; stderr=%s", handled, code, tc.wantCode, &stderr)
			}
			if (installCalls == 1) != tc.wantInstall {
				t.Errorf("install calls=%d, want install=%v", installCalls, tc.wantInstall)
			}
			if !strings.Contains(stderr.String(), "Install the entire-graph plugin?") || !strings.Contains(stderr.String(), "[Y/n]") {
				t.Errorf("missing Yes-default prompt: %q", stderr.String())
			}
			if stdout.Len() != 0 {
				t.Errorf("installation polluted stdout: %q", stdout.String())
			}
			got, err := os.ReadFile(argFile)
			if tc.wantRun {
				if err != nil || string(got) != strings.Join(args[1:], "\n")+"\n" {
					t.Errorf("forwarded args=%q err=%v", got, err)
				}
			} else if !os.IsNotExist(err) {
				t.Errorf("plugin unexpectedly ran: args=%q err=%v", got, err)
			}
			if tc.installErr != nil && !strings.Contains(stderr.String(), tc.installErr.Error()) {
				t.Errorf("missing install failure: %q", stderr.String())
			}
		})
	}
}

